/**
 * Classifies a failed session check (GET /auth/me, or any API call) into the
 * only three answers the app acts on. Shared by the browser (axios errors)
 * and the Next.js middleware (fetch responses) so both sides agree:
 *
 * - "unauthenticated": our backend said the token is missing or invalid
 *   (401). The only answer that sends a user to sign-in.
 * - "forbidden": our backend said the user may not do this (403 with a JSON
 *   body). Sends the user to /unauthorized.
 * - "unavailable": everything else. Network errors, timeouts, 5xx, 429, and
 *   anything generated by Cloudflare at the edge (WAF block, rate limit,
 *   challenge). Those arrive as HTML bodies, carry a `cf-mitigated` header,
 *   or have no status at all because the browser hid a response without CORS
 *   headers. Never navigate on these: show an error state and retry.
 *
 * Dependency-free on purpose: the middleware bundle runs on the edge runtime.
 */
export type AuthFailureKind = "unauthenticated" | "forbidden" | "unavailable";

export interface AuthFailureInput {
  /** HTTP status, or null/undefined when no response was received. */
  status?: number | null;
  /** Response content-type header, if any. */
  contentType?: string | null;
  /** Parsed object, or raw string, response body, if any. */
  body?: unknown;
  /** True when a `cf-mitigated` header was present (Cloudflare acted on the request). */
  mitigated?: boolean;
}

function isHtml(contentType: string | null | undefined, body: unknown): boolean {
  if (contentType && /text\/html/i.test(contentType)) return true;
  return typeof body === "string" && /^\s*<(!doctype|html)/i.test(body);
}

function isJson(contentType: string | null | undefined, body: unknown): boolean {
  if (contentType && /application\/(problem\+)?json/i.test(contentType)) return true;
  return body !== null && typeof body === "object";
}

export function classifyAuthFailure(input: AuthFailureInput): AuthFailureKind {
  const { status, contentType, body, mitigated } = input;
  if (!status) return "unavailable";
  if (mitigated || isHtml(contentType, body)) return "unavailable";
  if (status === 401) return "unauthenticated";
  if (status === 403 && isJson(contentType, body)) return "forbidden";
  return "unavailable";
}

interface ResponseLike {
  status?: number;
  headers?: Record<string, unknown> | { get?: (name: string) => unknown };
  data?: unknown;
}

function readHeader(headers: ResponseLike["headers"], name: string): string | null {
  if (!headers) return null;
  const record = headers as Record<string, unknown>;
  const direct = record[name] ?? record[name.toLowerCase()];
  if (typeof direct === "string") return direct;
  const getter = (headers as { get?: (n: string) => unknown }).get;
  if (typeof getter === "function") {
    const value = getter.call(headers, name);
    if (typeof value === "string") return value;
  }
  return null;
}

/** Axios-shaped error (anything with `.response`) → classification, without importing axios. */
export function classifyRequestError(err: unknown): AuthFailureKind {
  const response = (err as { response?: ResponseLike } | null | undefined)?.response;
  if (!response) return "unavailable";
  return classifyAuthFailure({
    status: response.status,
    contentType: readHeader(response.headers, "content-type"),
    body: response.data,
    mitigated: readHeader(response.headers, "cf-mitigated") !== null,
  });
}

/** HTTP status from an axios-shaped error, or null when there was no response. */
export function requestErrorStatus(err: unknown): number | null {
  const status = (err as { response?: { status?: number } } | null | undefined)?.response?.status;
  return typeof status === "number" ? status : null;
}
